DECLARE
    v_name employees.last_name%TYPE;
BEGIN
    SELECT last_name INTO v_name FROM employees WHERE employee_id = 9999;
    -- 9999에 해당하는 직원이 존재하지 않음
END;

DECLARE
    v_name employees.last_name%TYPE;
BEGIN
    SELECT last_name INTO v_name FROM employees WHERE last_name = 'King';
    -- 'King'이라는 성을 가진 직원이 2명 이상 존재
END;

DECLARE
    v_count NUMBER;
BEGIN
    SELECT COUNT(*) INTO v_count FROM employees WHERE department_id = 999;
    -- 999 부서에 직원이 0명이어도
END;
